// ---------------------------------------------------------------------------
// Golden plumbing (taxonomy_corpus.golden.json).
// ---------------------------------------------------------------------------

func goldenBytes(t *testing.T, name string) []byte {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("testdata", name))
	if err != nil {
		t.Fatalf("read golden %s (generate with testdiff/goldens/dump_taxonomy.py): %v", name, err)
	}
	return raw
}

func loadCorpus(t *testing.T) map[string]any {
	t.Helper()
	var doc map[string]any
	if err := json.Unmarshal(goldenBytes(t, "taxonomy_corpus.golden.json"), &doc); err != nil {
		t.Fatalf("decode corpus: %v", err)
	}
	return doc
}

func corpusSection(t *testing.T, doc map[string]any, key string) []any {
	t.Helper()
	v, ok := doc[key].([]any)
	if !ok {
		t.Fatalf("corpus section %q missing or wrong shape", key)
	}
	return v
}

func corpusString(t *testing.T, v any) string {
	t.Helper()
	s, ok := v.(string)
	if !ok {
		t.Fatalf("corpus string field wrong type: %T", v)
	}
	return s
}

// loadFixtureTaxonomy parses the testdata fixture exactly the way the
// Python setUpClass does (load_taxonomy on the copied file).
func loadFixtureTaxonomy(t *testing.T) *Taxonomy {
	t.Helper()
	tax, err := LoadTaxonomy(filepath.Join("testdata", "website-library-categories.md"))
	if err != nil {
		t.Fatalf("load fixture: %v", err)
	}
	return tax
}

// asTaxonomyError asserts err is a *TaxonomyError and returns it.
func asTaxonomyError(t *testing.T, err error) *TaxonomyError {
	t.Helper()
	if err == nil {
		t.Fatalf("expected *TaxonomyError, got nil")
	}
	var te *TaxonomyError
	if !errors.As(err, &te) {
		t.Fatalf("expected *TaxonomyError, got %T: %v", err, err)
	}
	return te
}

