// Port of test_counts.
func TestCounts(t *testing.T) {
	tax := loadFixtureTaxonomy(t)
	if got := len(tax.Categories()); got != 14 {
		t.Fatalf("categories = %d, want 14", got)
	}
	n := 0
	for _, c := range tax.Categories() {
		n += len(c.Subcategories)
	}
	if n != 16 {
		t.Fatalf("subcategories = %d, want 16", n)
	}
}

// Port of test_tricky_names_parse_exactly.
func TestTrickyNamesParseExactly(t *testing.T) {
	tax := loadFixtureTaxonomy(t)
	for _, name := range []string{
		"Design", "AI Tools for Web & App Development",
		"AI Tools (General)", "Developer Tools",
		"Free Utilities & Everyday Tools",
		"Knowledge, Research & Reference", "Download Resources",
		"Music & Audio Discovery", "Security & Privacy Tools",
		"Crypto & Markets", "English Learning & Career Prep",
		"Geography & Urban Planning", "Living Abroad",
		"Random / Curiosities",
	} {
		if !tax.IsCategory(name) {
			t.Errorf("is_category(%q) = false", name)
		}
	}
}

