// Port of test_subcategory_sets.
func TestSubcategorySets(t *testing.T) {
	tax := loadFixtureTaxonomy(t)
	cases := []struct {
		name string
		want []string
	}{
		{"Design", []string{"Assets & Resources", "UI/UX & Product Design",
			"Print & Editorial Design", "Branding & Identity"}},
		{"Geography & Urban Planning", []string{
			"Urban Planning Courses & Learning", "Maps, GIS & Data Tools",
			"Case Studies & Reference"}},
		{"Developer Tools", []string{}},
		{"Living Abroad", []string{"Australia"}},
		{"Download Resources", []string{
			"Public Archives & Libraries", "Torrent & Shadow Libraries"}},
	}
	for _, tc := range cases {
		got := tax.SubcategoriesOf(tc.name)
		if fmt.Sprint(got) != fmt.Sprint(tc.want) {
			t.Errorf("subcategories_of(%q) = %v, want %v", tc.name, got, tc.want)
		}
	}
}

// Port of test_validation_is_exact_match.
func TestValidationIsExactMatch(t *testing.T) {
	tax := loadFixtureTaxonomy(t)
	if tax.IsCategory("design") {
		t.Error("is_category(design) = true; case matters")
	}
	if tax.IsCategory("Not A Category") {
		t.Error("is_category(Not A Category) = true")
	}
	if !tax.IsCategory(" Design ") {
		t.Error("is_category(' Design ') = false; whitespace is tolerated")
	}
	if tax.IsSubcategoryOf("Design", "Icons") {
		t.Error("is_subcategory_of(Design, Icons) = true")
	}
	if !tax.IsSubcategoryOf("Design", "UI/UX & Product Design") {
		t.Error("is_subcategory_of(Design, UI/UX & Product Design) = false")
	}
}

