// Port of test_folder_relpaths_are_safe_filenames.
func TestFolderRelpathsAreSafeFilenames(t *testing.T) {
	tax := loadFixtureTaxonomy(t)
	sep := string(os.PathSeparator) // the Python test asserts with os.sep
	got, err := tax.FolderRelpath("Design", "Assets & Resources")
	if err != nil {
		t.Fatalf("folder_relpath: %v", err)
	}
	if want := "Design" + sep + "Assets_Resources"; got != want {
		t.Fatalf("relpath = %q, want %q", got, want)
	}
	got, err = tax.FolderRelpath("AI Tools (General)", "")
	if err != nil {
		t.Fatalf("folder_relpath: %v", err)
	}
	if want := "AI_Tools_General_"; got != want {
		t.Fatalf("relpath = %q, want %q", got, want)
	}
	if _, err := tax.FolderRelpath("Nope", ""); err == nil {
		t.Fatal("unknown category accepted")
	} else {
		asTaxonomyError(t, err)
	}
	if _, err := tax.FolderRelpath("Design", "Not A Subcategory"); err == nil {
		t.Fatal("unknown subcategory accepted")
	} else {
		asTaxonomyError(t, err)
	}
}

