// TestGoldenShippedSnapshot pins the SHIPPED taxonomy parse (from the
// EMBEDDED assets copy — sha256-pinned to the reference bytes) and the
// fixture file copy's bytes.
func TestGoldenShippedSnapshot(t *testing.T) {
	doc := loadCorpus(t)
	snap := doc["shipped_snapshot"].(map[string]any)

	raw := assets.TaxonomyDefault
	sum := sha256.Sum256(raw)
	if got := hex.EncodeToString(sum[:]); got != corpusString(t, snap["sha256"]) {
		t.Fatalf("embedded shipped taxonomy sha256 = %s, want %s (regenerate via dump_taxonomy.py)",
			got, corpusString(t, snap["sha256"]))
	}
	if bytes.HasPrefix(raw, []byte{0xEF, 0xBB, 0xBF}) {
		t.Fatal("shipped taxonomy carries a BOM")
	}

	// The parse snapshot: names, per-category counts, judgment rules.
	tax, err := ParseTaxonomy(string(raw), "<TMP>/shipped.md")
	if err != nil {
		t.Fatalf("parse shipped: %v", err)
	}
	if got := tax.Summary(); got != corpusString(t, snap["summary"]) {
		t.Errorf("shipped summary = %q, want %q", got, corpusString(t, snap["summary"]))
	}
	var wantNames []string
	for _, s := range snap["names"].([]any) {
		wantNames = append(wantNames, corpusString(t, s))
	}
	if fmt.Sprint(tax.CategoryNames()) != fmt.Sprint(wantNames) {
		t.Fatalf("shipped names = %v, want %v", tax.CategoryNames(), wantNames)
	}
	for _, e := range snap["subcounts"].([]any) {
		p := e.([]any)
		name := corpusString(t, p[0])
		wantCount := int(p[1].(float64))
		if got := len(tax.Category(name).Subcategories); got != wantCount {
			t.Errorf("shipped %s subcategories = %d, want %d", name, got, wantCount)
		}
	}
	if tax.JudgmentRules() != corpusString(t, snap["judgment_rules"]) {
		t.Errorf("shipped judgment_rules drifted")
	}

	// The fixture copy in testdata must equal the reference bytes too.
	fixRaw := goldenBytes(t, "website-library-categories.md")
	fixSum := sha256.Sum256(fixRaw)
	if got := hex.EncodeToString(fixSum[:]); got != corpusString(t, snap["fixture_sha256"]) {
		t.Fatalf("fixture copy sha256 = %s, want %s", got, corpusString(t, snap["fixture_sha256"]))
	}
}

// TestLoadTaxonomyFromConfig pins the config override wiring: the
// taxonomy_path override wins; a missing file surfaces the read error.
func TestLoadTaxonomyFromConfig(t *testing.T) {
	path := filepath.Join(t.TempDir(), "custom.md")
	content := "### Custom Cat\nmy prose\n"
	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
		t.Fatalf("write custom taxonomy: %v", err)
	}
	tax, err := LoadTaxonomyFromConfig(map[string]any{"taxonomy_path": "  " + path + "  "})
	if err != nil {
		t.Fatalf("load from config: %v", err)
	}
	if !tax.IsCategory("Custom Cat") {
		t.Fatalf("custom category missing: %v", tax.CategoryNames())
	}

	// No override + no default file reachable → the read error, not a
	// parse error (constants.ResolveTaxonomyPath falls back to the
	// AppDir default, which does not exist under the test binary).
	_, err = LoadTaxonomyFromConfig(map[string]any{})
	if err == nil {
		t.Fatal("missing default taxonomy did not error")
	}
	asTaxonomyError(t, err)
}
